guided-practice.solution:
class Tally:
    def __init__(self):
        self.seen = {}

    def add(self, word):
        self.seen[word] = self.seen.get(word, 0) + 1

    def count(self, word):
        return self.seen.get(word, 0)


def tally_counts(words, wanted):
    tally = Tally()
    for word in words:
        tally.add(word)
    return [tally.count(w) for w in wanted]

