class Vault:
    def __init__(self, balance):
        self.balance = balance
        self.refusals = 0

    def deposit(self, amount):
        self.balance = self.balance + amount

    def withdraw(self, amount):
        if amount > self.balance:
            self.refusals = self.refusals + 1
        else:
            self.balance = self.balance - amount


def run_vaults(commands):
    vaults = {}
    for action, name, amount in commands:
        if action == "open":
            vaults[name] = Vault(amount)
        elif action == "deposit":
            vaults[name].deposit(amount)
        else:
            vaults[name].withdraw(amount)
    return {name: [v.balance, v.refusals] for name, v in vaults.items()}

def busiest_room(bookings):
    totals = {}
    for room, hours in bookings:
        totals[room] = totals.get(room, 0) + hours
    best = None
    for room in sorted(totals):
        if best is None or totals[room] > totals[best]:
            best = room
    if best is None:
        return ""
    return best

class Name:
    def __init__(self, first, last):
        self.first = first
        self.last = last

    def __eq__(self, other):
        if not isinstance(other, Name):
            return NotImplemented
        return self.first == other.first and self.last == other.last


def duplicate_count(entries):
    seen = []
    dupes = 0
    for first, last in entries:
        here = Name(first, last)
        if here in seen:
            dupes = dupes + 1
        else:
            seen.append(here)
    return dupes

class Robot:
    def __init__(self):
        self.x = 0
        self.y = 0
        self.facing = 0

    def turn(self, step):
        self.facing = (self.facing + step) % 4

    def forward(self):
        moves = [[0, 1], [1, 0], [0, -1], [-1, 0]]
        dx, dy = moves[self.facing]
        self.x = self.x + dx
        self.y = self.y + dy

    def report(self):
        return [self.x, self.y, "NESW"[self.facing]]


def robot_position(commands):
    robot = Robot()
    for command in commands:
        if command == "F":
            robot.forward()
        elif command == "R":
            robot.turn(1)
        else:
            robot.turn(-1)
    return robot.report()

