class Register:
    def __init__(self):
        self.admitted = []
        self.rejected = 0

    def offer(self, name):
        if name in self.admitted:
            self.rejected = self.rejected + 1
        else:
            self.admitted.append(name)


def register_report(names):
    register = Register()
    for name in names:
        register.offer(name)
    return [register.admitted, register.rejected]

