from dataclasses import dataclass


class Sample:
    label: str
    grams: int


Sample = dataclass(Sample)


def heaviest(rows):
    best = None
    for label, grams in rows:
        if best is None or grams > best.grams:
            best = Sample(label, grams)
    if best is None:
        return ""
    return repr(best)
